  (
    'csv-117',
    'الطب والعلاج',
    '2026-08-23T01:00:00Z',
    $j$[{"id":"dKKm2UCZ","text":"دَخَلنا مع رَسولِ اللهِ صلَّى اللهُ عليه وسلَّم على أبي سَيفٍ القَينِ، وكان ظِئرًا لإبراهيمَ عليه السَّلامُ، فأخَذَ رَسولُ اللهِ صلَّى اللهُ عليه وسلَّم إبراهيمَ، فقَبَّلَه، وشَمَّه، ثُمَّ دَخَلنا عليه بَعدَ ذلك وإبراهيمُ يَجودُ بنَفسِه، فجَعَلَت عَينا رَسولِ اللهِ صلَّى اللهُ عليه وسلَّم تَذرِفانِ، فقال له عبدُ الرَّحمَنِ بنُ عَوفٍ رَضيَ اللهُ عنه: وأنتَ يا رَسولَ اللهِ؟ فقال: يا ابنَ عَوفٍ إنَّها رَحمةٌ، ثُمَّ أتبَعَها بأُخرى، فقال صلَّى اللهُ عليه وسلَّم: إنَّ العَينَ تَدمَعُ، والقَلبَ يَحزَنُ، ولا نَقولُ إلَّا ما يَرضى رَبُّنا، وإنَّا بفِراقِكَ يا إبراهيمُ لَمَحزونونَ.","rawi":"أنس بن مالك","book":"صحيح البخاري","ref":"1303","grade":"[صحيح]","takhrij":"أخرجه البخاري (1303)، ومسلم (2315)","categories":[{"id":"8b61cc8ce2086a05ed92a2943a90633f","name":"جنائز وموت - البكاء على الميت"},{"id":"e5e1d1495f4bde519317042bb036d595","name":"رقائق وزهد - الحزن والبكاء"},{"id":"fa344dd4bbf0ffb20f5ca6db5a6d8808","name":"فضائل النبي وصفته ودلائل النبوة - رحمته"},{"id":"4a9b4d17ea0f23e49dc1a032ac8c1114","name":"مناقب وفضائل - إبراهيم بن النبي صلى الله عليه وسلم"},{"id":"5c7577c95e","name":"جنائز وموت - الحزن لموت الأفاضل"}]}]$j$::jsonb,
