    ('csv-197', 'service', 'ما أكَلَ أحَدٌ طَعامًا قَطُّ خَيرًا مِن أن يَأكُلَ مِن عَمَلِ يَدِه، وإنَّ نَبيَّ اللهِ داوُدَ عليه السَّلامُ كان يَأكُلُ مِن عَمَلِ يَدِه.'),
    ('csv-198', 'self', 'ليس الشَّديدُ بالصُّرَعةِ، إنَّما الشَّديدُ الذي يَملِكُ نَفسَه عِندَ الغَضَبِ.'),
    ('csv-199', 'people', 'مَن كان يُؤمِنُ باللهِ واليَومِ الآخِرِ فليُكرِمْ ضَيفَه، ومَن كان يُؤمِنُ باللهِ واليَومِ الآخِرِ فليَصِلْ رَحِمَه، ومَن كان يُؤمِنُ باللهِ واليَومِ الآخِرِ فليَقُلْ خَيرًا أو ليَصمُتْ.'),
    ('csv-200', 'people', 'مَن كان يُؤمِنُ باللهِ واليَومِ الآخِرِ فليُكرِمْ ضَيفَه، ومَن كان يُؤمِنُ باللهِ واليَومِ الآخِرِ فليَصِلْ رَحِمَه، ومَن كان يُؤمِنُ باللهِ واليَومِ الآخِرِ فليَقُلْ خَيرًا أو ليَصمُتْ.'),
    ('csv-201', 'self', 'ليس الشَّديدُ بالصُّرَعةِ، إنَّما الشَّديدُ الذي يَملِكُ نَفسَه عِندَ الغَضَبِ.'),
    ('csv-202', 'learning', 'طلبُ العلمِ فريضةٌ على كلِ مسلمٍ'),
    ('csv-203', 'craft', 'مَن يُرِدِ اللهُ به خَيرًا يُفَقِّهْه في الدِّينِ، وإنَّما أنا قاسِمٌ ويُعطي اللهُ.'),
    ('csv-204', 'service', 'ما أكَلَ أحَدٌ طَعامًا قَطُّ خَيرًا مِن أن يَأكُلَ مِن عَمَلِ يَدِه، وإنَّ نَبيَّ اللهِ داوُدَ عليه السَّلامُ كان يَأكُلُ مِن عَمَلِ يَدِه.'),
    ('csv-205', 'worship', 'قال اللهُ عزَّ وجلَّ: أنا عِندَ ظَنِّ عَبدي بي، وأنا معهُ حَيثُ يَذكُرُني، واللهِ لَلَّهُ أفرَحُ بتَوبةِ عَبدِه مِن أحَدِكُم يَجِدُ ضالَّتَه بالفَلاةِ، ومَن تَقَرَّبَ إلَيَّ شِبرًا تَقَرَّبتُ إليه ذِراعًا، ومَن تَقَرَّبَ إلَيَّ ذِراعًا تَقَرَّبتُ إليه باعًا، وإذا أقبَلَ إلَيَّ يَمشي أقبَلتُ إليه أُهَروِلُ.'),
    ('csv-206', 'learning', 'مَن يُرِدِ اللهُ به خَيرًا يُفَقِّهْه في الدِّينِ، وإنَّما أنا قاسِمٌ ويُعطي اللهُ.'),
    ('csv-208', 'people', 'مَن كان يُؤمِنُ باللهِ واليَومِ الآخِرِ فليُكرِمْ ضَيفَه، ومَن كان يُؤمِنُ باللهِ واليَومِ الآخِرِ فليَصِلْ رَحِمَه، ومَن كان يُؤمِنُ باللهِ واليَومِ الآخِرِ فليَقُلْ خَيرًا أو ليَصمُتْ.'),
    ('csv-209', 'knowledge', 'مَن يُرِدِ اللهُ به خَيرًا يُفَقِّهْه في الدِّينِ، وإنَّما أنا قاسِمٌ ويُعطي اللهُ.'),
    ('csv-210', 'worship', 'من قرأ سورةَ الكهفِ في يومِ الجمعةِ، أضاء له من النورِ ما بين الجمُعتَينِ'),
    ('csv-211', 'learning', 'مَن يُرِدِ اللهُ به خَيرًا يُفَقِّهْه في الدِّينِ، وإنَّما أنا قاسِمٌ ويُعطي اللهُ.'),
    ('csv-212', 'learning', 'مَن يُرِدِ اللهُ به خَيرًا يُفَقِّهْه في الدِّينِ، وإنَّما أنا قاسِمٌ ويُعطي اللهُ.'),
    ('csv-213', 'self', 'تبسُّمُكَ في وجهِ أخيكَ لكَ صدقةٌ، وأمرُك بالمعروفِ ونهيُك عن المنكرِ صدقةٌ، وإرشادُك الرَّجلَ في أرضِ الضَّلالِ لكَ صدَقةٌ، وإماطتُك الأَذى والشَّوكَ والعَظمَ عن الطَّريقِ لكَ صدقةٌ، وإفراغُك من دَلْوِكَ في دَلْوِ أخيكَ لكَ صدقةٌ.'),
    ('csv-215', 'self', 'آيةُ المُنافِقِ ثَلاثٌ: إذا حَدَّثَ كَذَبَ، وإذا وعَدَ أخلَفَ، وإذا اؤتُمِنَ خانَ'),
    ('csv-217', 'worship', 'واللهِ إنِّي لَأستَغفِرُ اللهَ وأتوبُ إليه في اليَومِ أكثَرَ مِن سَبعينَ مَرَّةً.'),
    ('csv-219', 'daily', 'ثِنتانِ حَفِظتُهما عن رَسولِ اللهِ صلَّى اللهُ عليه وسلَّم، قال: إنَّ اللَّهَ كَتَبَ الإحسانَ على كُلِّ شيءٍ، فإذا قَتَلتُم فأحسِنوا القِتلةَ، وإذا ذَبَحتُم فأحسِنوا الذَّبحَ، وليُحِدَّ أحَدُكُم شَفرَتَه، فليُرِحْ ذَبيحَتَه.'),
    ('csv-221', 'people', 'مَن عادَ مَريضًا لَم يَزَلْ في خُرفةِ الجَنَّةِ، قيلَ: يا رَسولَ اللهِ، وما خُرفةُ الجَنَّةِ؟ قال: جَناها.'),
    ('csv-223', 'service', 'يا أَيُّها الناسُ ! أَفْشُوا السلامَ ، و أطْعِمُوا الطعامَ، وصِلُوا الأرحامَ، وصَلُّوا بالليلِ والناسُ نِيَامٌ، تَدْخُلوا الجنةَ بسَلامٍ'),
    ('csv-225', 'self', 'يا عائِشةُ، إنَّ اللهَ رَفيقٌ يُحِبُّ الرِّفقَ، ويُعطي على الرِّفقِ ما لا يُعطي على العُنفِ، وما لا يُعطي على ما سِواه.'),
    ('csv-228', 'people', 'ما زالَ جِبريلُ يوصيني بالجارِ، حتَّى ظَنَنتُ أنَّه سَيورِّثُه.'),
    ('csv-230', 'people', 'مَن أحَبَّ أن يُبسَطَ له في رِزقِه، ويُنسَأَ له في أثَرِه، فليَصِلْ رَحِمَه.'),
    ('csv-232', 'worship', 'صَلاةُ الجَماعةِ تَفضُلُ صَلاةَ الفَذِّ بسَبعٍ وعِشرينَ دَرَجةً.'),
    ('csv-234', 'worship', 'لَو يَعلَمُ النَّاسُ ما في النِّداءِ والصَّفِّ الأوَّلِ، ثُمَّ لَم يَجِدوا إلَّا أن يَستَهِموا عليه لاستَهَموا، ولو يَعلَمونَ ما في التَّهجير، لاستَبَقوا إليه، ولو يَعلَمونَ ما في العَتَمةِ والصُّبحِ لأتَوهُما ولو حَبوًا.'),
    ('csv-236', 'worship', 'صِيامُ يومِ عَرَفَةَ، إِنِّي أحْتَسِبُ على اللهِ أنْ يُكَفِّرَ السنَةَ التي قَبلَهُ، و السنَةَ التي بَعدَهُ، و صِيامُ يومِ عاشُوراءَ، إِنِّي أحْتَسِبُ على اللهِ أنْ يُكَفِّرَ السنَةَ التِي قَبْلَهُ'),
    ('csv-238', 'self', 'أُوصيك بتقوى اللهِ، فإنها زَينٌ لأمرِك كلِّه. قلتُ : يا رسولَ اللهِ ! زِدْني. قال : عليك بتلاوة القرآنِ، وذكرِ اللهِ عزَّ وجلَّ؛ فإنه ذِكرٌ لك في السماءِ، ونورٌ لك في الأرضِ. قلتُ : يا رسولَ اللهِ ! زِدْني. قال : وإياك وكثرةَ الضَّحِكِ، فإنه يميتُ القلبَ، ويذهبُ بنور الوجهِ. قلتُ : زِدْني، قال : قُلِ الحقَّ وإن كان مُرًّا. قلتُ : زِدْني. قال : لا تَخَفْ في اللهِ لومةَ لائمٍ.'),
    ('csv-240', 'service', 'أنا وكافِلُ اليَتيمِ في الجَنَّةِ هَكَذا، وقال بإصبَعَيه السَّبَّابةِ والوُسطى.'),
    ('csv-242', 'self', 'إنَّ الغضَبَ مِنَ الشيطانِ، وإنَّ الشيطانَ خُلِقَ منَ النارِ، وإنَّما تُطفأُ النارُ بالماءِ، فإذا غضِبَ أحَدُكم فلْيَتوضَّأْ.'),
    ('csv-244', 'worship', 'سَألتُ النَّبيَّ صلَّى اللهُ عليه وسلَّم: أيُّ العَمَلِ أحَبُّ إلى اللهِ؟ قال: الصَّلاةُ على وقتِها، قال: ثُمَّ أيٌّ؟ قال: برُّ الوالِدَينِ، قال: ثُمَّ أيٌّ؟ قال: الجِهادُ في سَبيلِ اللهِ، قال: حدَّثَني بهِنَّ، ولَوِ استَزَدتُه لَزادَني.'),
    ('csv-246', 'stewardship', 'ما مِن مُسلِمٍ يَغرِسُ غَرسًا، أو يَزرَعُ زَرعًا، فيَأكُلُ منه طَيرٌ أو إنسانٌ أو بَهيمةٌ إلَّا كان له به صَدَقةٌ.'),
    ('csv-248', 'self', 'إنَّ الغضَبَ مِنَ الشيطانِ، وإنَّ الشيطانَ خُلِقَ منَ النارِ، وإنَّما تُطفأُ النارُ بالماءِ، فإذا غضِبَ أحَدُكم فلْيَتوضَّأْ.'),
    ('csv-250', 'people', 'لا يُؤمِنُ أحَدُكُم حتَّى يُحِبَّ لأخيه ما يُحِبُّ لنَفسِه.')
), upserted as (
  insert into intentions (slug, act_group, source_original, published_at)
  select slug, act_group, source_original, null from rows
  on conflict (slug) do update set
    act_group = excluded.act_group,
    source_original = excluded.source_original,
    published_at = null
  returning id, slug
)
